draw:
var th = p.angle * Math.PI / 180;
var A = p.magA, B = p.magB;
var pad = 34;
var span = 12;
var s = Math.min((W - 2 * pad) / (2 * span), (H - 2 * pad) / (1.6 * span));
var ox = W * 0.28, oy = H * 0.72;
var X = function (x) { return ox + x * s; };
var Y = function (y) { return oy - y * s; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), hl = 9;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - hl * Math.cos(a - 0.4), y2 - hl * Math.sin(a - 0.4));
  ctx.lineTo(x2 - hl * Math.cos(a + 0.4), y2 - hl * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

// B lies along +x, A is tilted up by th
var bx = B, by = 0;
var axv = A * Math.cos(th), ayv = A * Math.sin(th);
var proj = A * Math.cos(th);

// baseline through B, extended
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(-2), Y(0)); ctx.lineTo(X(span), Y(0)); ctx.stroke();

// projection bar sitting on B's line
ctx.strokeStyle = C.figure; ctx.lineWidth = 6;
ctx.beginPath(); ctx.moveTo(X(0), Y(0) + 0); ctx.lineTo(X(proj), Y(0)); ctx.stroke();

// dropped perpendicular
ctx.strokeStyle = C.figure; ctx.lineWidth = 1; ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(axv), Y(ayv)); ctx.lineTo(X(proj), Y(0)); ctx.stroke();
ctx.setLineDash([]);

arrow(X(0), Y(0), X(bx), Y(by), C.rule, 2.5);
arrow(X(0), Y(0), X(axv), Y(ayv), C.accent, 2.5);

// angle arc
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.arc(X(0), Y(0), 24, 0, -th, true); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("B", X(bx) + 6, Y(0) + 16);
ctx.fillText("A", X(axv) + 6, Y(ayv) - 4);
ctx.fillText("A cos(theta) = " + proj.toFixed(2), X(proj / 2) - 34, Y(0) + 26);
ctx.fillStyle = C.figure;
ctx.fillText(p.angle.toFixed(0) + " deg", X(0) + 28, Y(0) - 8);

var dp = A * B * Math.cos(th);
ctx.fillStyle = C.ink;
ctx.fillText("shadow of A on B, times the length of B", W * 0.06, 20);

out.note = "A.B = |A||B|cos(theta) = " + A.toFixed(1) + " x " + B.toFixed(1) + " x " + Math.cos(th).toFixed(3) + " = " + dp.toFixed(2) + "   |   projection of A onto B = " + proj.toFixed(2) + (Math.abs(dp) < 0.05 ? "   (perpendicular)" : "");
